import React, { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Search, Filter, Download, Eye, X, ChevronLeft, ChevronRight,
  CheckCircle, XCircle, Clock, CalendarDays, IndianRupee, User,
  Phone, Mail, Package, MapPin, ChevronDown,
} from 'lucide-react';
import toast from 'react-hot-toast';

const mockBookings = [
  { id: 'BK-2026-001', user: { name: 'Arjun Sharma', email: 'arjun@email.com', phone: '+91-9876543210' }, package: 'Golden Triangle Tour', destination: 'Rajasthan', travelDate: '2026-04-20', bookingDate: '2026-03-15', travelers: 4, amount: 45000, status: 'confirmed', paymentStatus: 'paid' },
  { id: 'BK-2026-002', user: { name: 'Priya Patel', email: 'priya@email.com', phone: '+91-9876543211' }, package: 'Kerala Backwaters', destination: 'Kerala', travelDate: '2026-04-22', bookingDate: '2026-03-20', travelers: 2, amount: 38500, status: 'pending', paymentStatus: 'partial' },
  { id: 'BK-2026-003', user: { name: 'Rahul Gupta', email: 'rahul@email.com', phone: '+91-9876543212' }, package: 'Goa Beach Package', destination: 'Goa', travelDate: '2026-04-18', bookingDate: '2026-03-10', travelers: 6, amount: 22000, status: 'completed', paymentStatus: 'paid' },
  { id: 'BK-2026-004', user: { name: 'Ananya Singh', email: 'ananya@email.com', phone: '+91-9876543213' }, package: 'Manali Snow Trek', destination: 'Himachal', travelDate: '2026-04-25', bookingDate: '2026-03-22', travelers: 3, amount: 31000, status: 'confirmed', paymentStatus: 'paid' },
  { id: 'BK-2026-005', user: { name: 'Vikram Reddy', email: 'vikram@email.com', phone: '+91-9876543214' }, package: 'Andaman Explorer', destination: 'Andaman', travelDate: '2026-05-02', bookingDate: '2026-03-28', travelers: 2, amount: 55000, status: 'pending', paymentStatus: 'unpaid' },
  { id: 'BK-2026-006', user: { name: 'Kavya Nair', email: 'kavya@email.com', phone: '+91-9876543215' }, package: 'Rajasthan Heritage', destination: 'Rajasthan', travelDate: '2026-04-28', bookingDate: '2026-03-18', travelers: 5, amount: 41500, status: 'cancelled', paymentStatus: 'refunded' },
  { id: 'BK-2026-007', user: { name: 'Rohan Mehta', email: 'rohan@email.com', phone: '+91-9876543216' }, package: 'Varanasi Spiritual', destination: 'UP', travelDate: '2026-04-30', bookingDate: '2026-03-25', travelers: 2, amount: 18000, status: 'confirmed', paymentStatus: 'paid' },
  { id: 'BK-2026-008', user: { name: 'Divya Joshi', email: 'divya@email.com', phone: '+91-9876543217' }, package: 'Darjeeling Tea Tour', destination: 'West Bengal', travelDate: '2026-05-05', bookingDate: '2026-03-30', travelers: 3, amount: 27500, status: 'pending', paymentStatus: 'partial' },
  { id: 'BK-2026-009', user: { name: 'Aditya Kumar', email: 'aditya@email.com', phone: '+91-9876543218' }, package: 'Coorg Plantation', destination: 'Karnataka', travelDate: '2026-04-19', bookingDate: '2026-03-12', travelers: 4, amount: 33000, status: 'completed', paymentStatus: 'paid' },
  { id: 'BK-2026-010', user: { name: 'Sneha Iyer', email: 'sneha@email.com', phone: '+91-9876543219' }, package: 'Leh Ladakh Ride', destination: 'Ladakh', travelDate: '2026-05-10', bookingDate: '2026-04-01', travelers: 8, amount: 62000, status: 'confirmed', paymentStatus: 'paid' },
];

const STATUS_CONFIG = {
  confirmed: { label: 'Confirmed', classes: 'bg-blue-100 text-blue-700', icon: CheckCircle },
  pending: { label: 'Pending', classes: 'bg-amber-100 text-amber-700', icon: Clock },
  completed: { label: 'Completed', classes: 'bg-emerald-100 text-emerald-700', icon: CheckCircle },
  cancelled: { label: 'Cancelled', classes: 'bg-red-100 text-red-700', icon: XCircle },
};

const PAYMENT_CONFIG = {
  paid: { label: 'Paid', classes: 'bg-emerald-100 text-emerald-700' },
  partial: { label: 'Partial', classes: 'bg-orange-100 text-orange-700' },
  unpaid: { label: 'Unpaid', classes: 'bg-red-100 text-red-700' },
  refunded: { label: 'Refunded', classes: 'bg-gray-100 text-gray-500' },
};

const StatusBadge = ({ status, config }) => {
  const cfg = config[status] || { label: status, classes: 'bg-gray-100 text-gray-700' };
  return <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold ${cfg.classes}`}>{cfg.label}</span>;
};

const DetailRow = ({ label, value, icon: Icon }) => (
  <div className="flex items-start gap-3">
    {Icon && <Icon className="w-4 h-4 text-gray-400 mt-0.5 flex-shrink-0" />}
    <div>
      <p className="text-xs font-medium text-gray-500">{label}</p>
      <p className="text-sm text-gray-800 font-medium">{value}</p>
    </div>
  </div>
);

const AdminBookingManagementPage = () => {
  const [bookings, setBookings] = useState(mockBookings);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [selectedBooking, setSelectedBooking] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  const perPage = 8;

  const filtered = useMemo(() => {
    return bookings.filter((b) => {
      const matchSearch = b.id.toLowerCase().includes(search.toLowerCase()) ||
        b.user.name.toLowerCase().includes(search.toLowerCase()) ||
        b.package.toLowerCase().includes(search.toLowerCase());
      const matchStatus = statusFilter === 'all' || b.status === statusFilter;
      const matchFrom = !dateFrom || b.travelDate >= dateFrom;
      const matchTo = !dateTo || b.travelDate <= dateTo;
      return matchSearch && matchStatus && matchFrom && matchTo;
    });
  }, [bookings, search, statusFilter, dateFrom, dateTo]);

  const totalPages = Math.ceil(filtered.length / perPage);
  const paginated = filtered.slice((currentPage - 1) * perPage, currentPage * perPage);

  const updateStatus = (id, newStatus) => {
    setBookings((prev) => prev.map((b) => b.id === id ? { ...b, status: newStatus } : b));
    toast.success(`Booking ${id} marked as ${newStatus}`);
    setSelectedBooking((prev) => prev ? { ...prev, status: newStatus } : null);
  };

  const exportCSV = () => {
    const headers = ['Booking ID', 'User', 'Package', 'Travel Date', 'Travelers', 'Amount', 'Status'];
    const rows = filtered.map((b) => [b.id, b.user.name, b.package, b.travelDate, b.travelers, b.amount, b.status]);
    const csvContent = [headers, ...rows].map((r) => r.join(',')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `bookings-${new Date().toISOString().slice(0, 10)}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    toast.success('CSV exported!');
  };

  return (
    <div className="min-h-screen bg-gray-50 p-4 sm:p-6 lg:p-8">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Booking Management</h1>
          <p className="text-sm text-gray-500">{bookings.length} total bookings</p>
        </div>
        <button onClick={exportCSV} className="flex items-center gap-2 px-5 py-2.5 bg-emerald-600 text-white text-sm font-semibold rounded-xl shadow-sm hover:bg-emerald-700 transition-colors">
          <Download className="w-4 h-4" /> Export CSV
        </button>
      </div>

      {/* Stats Bar */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-5">
        {['confirmed', 'pending', 'completed', 'cancelled'].map((status) => {
          const count = bookings.filter((b) => b.status === status).length;
          const cfg = STATUS_CONFIG[status];
          return (
            <button
              key={status}
              onClick={() => setStatusFilter(statusFilter === status ? 'all' : status)}
              className={`p-3 rounded-xl border transition-all text-left ${statusFilter === status ? 'ring-2 ring-[#0B4F6C] border-[#0B4F6C]' : 'bg-white border-gray-100 hover:border-gray-200'} bg-white shadow-sm`}
            >
              <p className="text-xl font-bold text-gray-900">{count}</p>
              <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-semibold ${cfg.classes} mt-1`}>{cfg.label}</span>
            </button>
          );
        })}
      </div>

      {/* Filters */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 mb-5">
        <div className="flex flex-col sm:flex-row gap-3">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search by ID, user, package..." className="w-full pl-9 pr-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#0B4F6C]/30 focus:border-[#0B4F6C]" />
          </div>
          <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} className="border border-gray-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none bg-white">
            <option value="all">All Status</option>
            {Object.keys(STATUS_CONFIG).map((s) => <option key={s} value={s}>{STATUS_CONFIG[s].label}</option>)}
          </select>
          <input type="date" value={dateFrom} onChange={(e) => setDateFrom(e.target.value)} className="border border-gray-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#0B4F6C]/30 focus:border-[#0B4F6C]" />
          <input type="date" value={dateTo} onChange={(e) => setDateTo(e.target.value)} className="border border-gray-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#0B4F6C]/30 focus:border-[#0B4F6C]" />
        </div>
      </div>

      {/* Table */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="border-b border-gray-100 bg-gray-50/50">
                <th className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">Booking ID</th>
                <th className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">User</th>
                <th className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3 hidden md:table-cell">Package</th>
                <th className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3 hidden lg:table-cell">Travel Date</th>
                <th className="text-right text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">Amount</th>
                <th className="text-center text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">Status</th>
                <th className="text-center text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {paginated.map((booking, index) => (
                <motion.tr key={booking.id} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: index * 0.04 }} className="hover:bg-gray-50/50 transition-colors cursor-pointer" onClick={() => setSelectedBooking(booking)}>
                  <td className="px-4 py-3.5"><span className="text-sm font-mono font-semibold text-[#0B4F6C]">{booking.id}</span></td>
                  <td className="px-4 py-3.5">
                    <div className="flex items-center gap-2">
                      <div className="w-7 h-7 rounded-full bg-gradient-to-br from-[#0B4F6C] to-[#00B4D8] flex items-center justify-center text-white text-xs font-bold flex-shrink-0">{booking.user.name.charAt(0)}</div>
                      <span className="text-sm font-medium text-gray-800">{booking.user.name}</span>
                    </div>
                  </td>
                  <td className="px-4 py-3.5 hidden md:table-cell"><span className="text-sm text-gray-600">{booking.package}</span></td>
                  <td className="px-4 py-3.5 hidden lg:table-cell"><span className="text-sm text-gray-600">{new Date(booking.travelDate).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}</span></td>
                  <td className="px-4 py-3.5 text-right"><span className="text-sm font-semibold text-gray-800">₹{booking.amount.toLocaleString('en-IN')}</span></td>
                  <td className="px-4 py-3.5 text-center"><StatusBadge status={booking.status} config={STATUS_CONFIG} /></td>
                  <td className="px-4 py-3.5 text-center" onClick={(e) => e.stopPropagation()}>
                    <button onClick={() => setSelectedBooking(booking)} className="p-1.5 text-gray-400 hover:text-[#0B4F6C] hover:bg-blue-50 rounded-lg transition-colors"><Eye className="w-4 h-4" /></button>
                  </td>
                </motion.tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="px-4 py-3 border-t border-gray-100 flex items-center justify-between">
            <p className="text-sm text-gray-500">Showing {(currentPage - 1) * perPage + 1}–{Math.min(currentPage * perPage, filtered.length)} of {filtered.length}</p>
            <div className="flex gap-1">
              <button disabled={currentPage === 1} onClick={() => setCurrentPage((p) => p - 1)} className="p-1.5 border border-gray-200 rounded-lg disabled:opacity-40 hover:bg-gray-50"><ChevronLeft className="w-4 h-4" /></button>
              <button disabled={currentPage === totalPages} onClick={() => setCurrentPage((p) => p + 1)} className="p-1.5 border border-gray-200 rounded-lg disabled:opacity-40 hover:bg-gray-50"><ChevronRight className="w-4 h-4" /></button>
            </div>
          </div>
        )}
      </div>

      {/* Detail Drawer */}
      <AnimatePresence>
        {selectedBooking && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-black/50 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4">
            <motion.div initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }} transition={{ type: 'spring', damping: 25 }} className="bg-white rounded-t-3xl sm:rounded-2xl w-full sm:max-w-lg shadow-2xl max-h-[90vh] overflow-y-auto">
              <div className="sticky top-0 bg-white border-b border-gray-100 p-5 flex items-center justify-between">
                <div>
                  <h3 className="text-lg font-bold text-gray-900">{selectedBooking.id}</h3>
                  <div className="flex gap-2 mt-1">
                    <StatusBadge status={selectedBooking.status} config={STATUS_CONFIG} />
                    <StatusBadge status={selectedBooking.paymentStatus} config={PAYMENT_CONFIG} />
                  </div>
                </div>
                <button onClick={() => setSelectedBooking(null)} className="p-2 hover:bg-gray-100 rounded-lg transition-colors"><X className="w-5 h-5" /></button>
              </div>

              <div className="p-5 space-y-6">
                {/* User Info */}
                <div>
                  <h4 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">Customer Details</h4>
                  <div className="bg-gray-50 rounded-xl p-4 grid grid-cols-1 sm:grid-cols-2 gap-3">
                    <DetailRow label="Name" value={selectedBooking.user.name} icon={User} />
                    <DetailRow label="Phone" value={selectedBooking.user.phone} icon={Phone} />
                    <DetailRow label="Email" value={selectedBooking.user.email} icon={Mail} />
                    <DetailRow label="Travelers" value={selectedBooking.travelers} icon={User} />
                  </div>
                </div>

                {/* Package Info */}
                <div>
                  <h4 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">Package Details</h4>
                  <div className="bg-gray-50 rounded-xl p-4 grid grid-cols-1 sm:grid-cols-2 gap-3">
                    <DetailRow label="Package" value={selectedBooking.package} icon={Package} />
                    <DetailRow label="Destination" value={selectedBooking.destination} icon={MapPin} />
                    <DetailRow label="Travel Date" value={new Date(selectedBooking.travelDate).toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' })} icon={CalendarDays} />
                    <DetailRow label="Total Amount" value={`₹${selectedBooking.amount.toLocaleString('en-IN')}`} icon={IndianRupee} />
                  </div>
                </div>

                {/* Actions */}
                {selectedBooking.status !== 'cancelled' && selectedBooking.status !== 'completed' && (
                  <div>
                    <h4 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">Update Status</h4>
                    <div className="flex flex-wrap gap-2">
                      {selectedBooking.status === 'pending' && (
                        <button onClick={() => updateStatus(selectedBooking.id, 'confirmed')} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white text-sm font-semibold rounded-lg hover:bg-blue-700 transition-colors">
                          <CheckCircle className="w-4 h-4" /> Confirm
                        </button>
                      )}
                      {(selectedBooking.status === 'confirmed' || selectedBooking.status === 'pending') && (
                        <button onClick={() => updateStatus(selectedBooking.id, 'completed')} className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white text-sm font-semibold rounded-lg hover:bg-emerald-700 transition-colors">
                          <CheckCircle className="w-4 h-4" /> Mark Complete
                        </button>
                      )}
                      <button onClick={() => updateStatus(selectedBooking.id, 'cancelled')} className="flex items-center gap-2 px-4 py-2 bg-red-500 text-white text-sm font-semibold rounded-lg hover:bg-red-600 transition-colors">
                        <XCircle className="w-4 h-4" /> Cancel
                      </button>
                    </div>
                  </div>
                )}
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default AdminBookingManagementPage;
